cat <<'EOF' > /workspace/src/args.go
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

const helpShort = `sd v1.0.0
An intuitive find & replace CLI

Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>          The regexp or string (if using ` + "`" + `-F` + "`" + `) to search for
  <REPLACE_WITH>  What to replace each match with. Unless in string mode, you may use captured
                  values like $1, $2, etc
  [FILES]...      The path to file(s). This is optional - sd can also read from STDIN

Options:
  -p, --preview                   Display changes in a human reviewable format (the specifics of the
                                  format are likely to change in the future)
  -F, --fixed-strings             Treat FIND and REPLACE_WITH args as literal strings
  -n, --max-replacements <LIMIT>  Limit the number of replacements that can occur per file. 0
                                  indicates unlimited replacements [default: 0]
  -f, --flags <FLAGS>             Regex flags. May be combined (like ` + "`" + `-f mc` + "`" + `).
  -h, --help                      Print help (see more with '--help')
  -V, --version                   Print version
`

const helpLong = `sd v1.0.0
An intuitive find & replace CLI

Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using ` + "`" + `-F` + "`" + `) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like ` + "`" + `-f mc` + "`" + `).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make ` + "`" + `.` + "`" + ` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
`

// parseArgs parses command-line arguments and returns args plus (exit_code, done).
// done=true indicates the program should exit with the given code.
func parseArgs(argv []string) (cliArgs, int, bool) {
	var args cliArgs
	var positional []string

	// Track which flags were set to build appropriate usage line
	setFlags := []string{}

	i := 0
	n := len(argv)
	var inPositional bool
	for i < n {
		arg := argv[i]
		if !inPositional && arg == "--" {
			inPositional = true
			i++
			continue
		}
		if !inPositional && strings.HasPrefix(arg, "--") {
			// Long flag
			name := arg[2:]
			var value string
			var hasValue bool
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				hasValue = true
				name = name[:idx]
			}
			switch name {
			case "help":
				fmt.Print(helpLong)
				return args, 0, true
			case "version":
				fmt.Println("sd " + version)
				return args, 0, true
			case "preview":
				if hasValue {
					usageErrorUnexpectedValue("--preview", setFlags)
					return args, 2, true
				}
				args.preview = true
				setFlags = append(setFlags, "--preview")
			case "fixed-strings":
				if hasValue {
					usageErrorUnexpectedValue("--fixed-strings", setFlags)
					return args, 2, true
				}
				args.fixedStrings = true
				setFlags = append(setFlags, "--fixed-strings")
			case "max-replacements":
				if !hasValue {
					if i+1 >= n {
						usageErrorMissingValue("--max-replacements <LIMIT>")
						return args, 2, true
					}
					value = argv[i+1]
					i++
				}
				v, err := strconv.ParseUint(value, 10, 64)
				if err != nil {
					usageErrorInvalidValue(value, "--max-replacements <LIMIT>", err)
					return args, 2, true
				}
				args.maxReplacements = v
				setFlags = append(setFlags, "--max-replacements")
			case "flags":
				if !hasValue {
					if i+1 >= n {
						usageErrorMissingValue("--flags <FLAGS>")
						return args, 2, true
					}
					value = argv[i+1]
					i++
				}
				args.flags = value
				setFlags = append(setFlags, "--flags")
			default:
				usageErrorUnknown(arg, setFlags)
				return args, 2, true
			}
			i++
			continue
		}
		if !inPositional && len(arg) >= 2 && arg[0] == '-' && arg != "-" {
			// Short flag(s)
			rest := arg[1:]
			consumed := false
			for j := 0; j < len(rest); j++ {
				ch := rest[j]
				switch ch {
				case 'h':
					fmt.Print(helpShort)
					return args, 0, true
				case 'V':
					fmt.Println("sd " + version)
					return args, 0, true
				case 'p':
					args.preview = true
					setFlags = append(setFlags, "--preview")
				case 'F':
					args.fixedStrings = true
					setFlags = append(setFlags, "--fixed-strings")
				case 'n':
					// value follows: either rest of arg or next arg
					var value string
					if j+1 < len(rest) {
						value = rest[j+1:]
						if len(value) > 0 && value[0] == '=' {
							value = value[1:]
						}
					} else {
						if i+1 >= n {
							usageErrorMissingValue("--max-replacements <LIMIT>")
							return args, 2, true
						}
						value = argv[i+1]
						i++
					}
					v, err := strconv.ParseUint(value, 10, 64)
					if err != nil {
						usageErrorInvalidValue(value, "--max-replacements <LIMIT>", err)
						return args, 2, true
					}
					args.maxReplacements = v
					setFlags = append(setFlags, "--max-replacements")
					// consumed rest of this arg
					j = len(rest)
				case 'f':
					var value string
					if j+1 < len(rest) {
						value = rest[j+1:]
						if len(value) > 0 && value[0] == '=' {
							value = value[1:]
						}
					} else {
						if i+1 >= n {
							usageErrorMissingValue("--flags <FLAGS>")
							return args, 2, true
						}
						value = argv[i+1]
						i++
					}
					args.flags = value
					setFlags = append(setFlags, "--flags")
					j = len(rest)
				default:
					usageErrorUnknown("-"+string(ch), setFlags)
					return args, 2, true
				}
				_ = consumed
			}
			i++
			continue
		}
		// Positional
		if arg == "" {
			// Empty positional - clap treats this as an error for files
			// We'll see specifically
			if len(positional) >= 2 {
				// [FILES]... - clap reports "a value is required for '[FILES]...' but none was supplied"
				usageErrorEmptyValue("[FILES]...")
				return args, 2, true
			}
		}
		positional = append(positional, arg)
		i++
	}

	if len(positional) < 1 {
		usageErrorMissingArgs([]string{"<FIND>", "<REPLACE_WITH>"}, setFlags)
		return args, 2, true
	}
	if len(positional) < 2 {
		usageErrorMissingArgs([]string{"<REPLACE_WITH>"}, setFlags)
		return args, 2, true
	}
	args.find = positional[0]
	args.replaceWith = positional[1]
	if len(positional) > 2 {
		// Check for empty files arguments
		for _, f := range positional[2:] {
			if f == "" {
				usageErrorEmptyValue("[FILES]...")
				return args, 2, true
			}
		}
		args.files = positional[2:]
	}
	return args, 0, false
}

func usageLine(setFlags []string) string {
	if len(setFlags) == 0 {
		return "Usage: executable <FIND> <REPLACE_WITH> [FILES]..."
	}
	// Deduplicate
	seen := map[string]bool{}
	uniq := []string{}
	for _, f := range setFlags {
		if !seen[f] {
			seen[f] = true
			uniq = append(uniq, f)
		}
	}
	return "Usage: executable " + strings.Join(uniq, " ") + " <FIND> <REPLACE_WITH> [FILES]..."
}

func usageErrorUnknown(arg string, setFlags []string) {
	fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n", arg)
	fmt.Fprintf(os.Stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg)
	fmt.Fprintln(os.Stderr, "Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...")
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorMissingValue(flagDesc string) {
	fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\n", flagDesc)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorEmptyValue(flagDesc string) {
	fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\n", flagDesc)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorInvalidValue(value, flagDesc string, err error) {
	msg := err.Error()
	if nerr, ok := err.(*strconv.NumError); ok {
		switch nerr.Err.Error() {
		case "value out of range":
			msg = "number too large to fit in target type"
		case "invalid syntax":
			msg = "invalid digit found in string"
		}
	}
	fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '%s': %s\n\n", value, flagDesc, msg)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorUnexpectedValue(flag string, setFlags []string) {
	// clap message for providing value to a flag that doesn't take one
	fmt.Fprintf(os.Stderr, "error: unexpected value provided for '%s'\n\n", flag)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorMissingArgs(missing []string, setFlags []string) {
	fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
	for _, m := range missing {
		fmt.Fprintln(os.Stderr, "  "+m)
	}
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, usageLine(setFlags))
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}
EOF
echo "created args.go"

