						i++
					}
					v, err := strconv.ParseUint(value, 10, 64)
					if err != nil {
						usageErrorInvalidValue(value, "--max-replacements <LIMIT>", err)
						return args, 2, true
					}
					args.maxReplacements = v
					setFlags = append(setFlags, "--max-replacements")
					// consumed rest of this arg
					j = len(rest)
				case 'f':
					var value string
					if j+1 < len(rest) {
						value = rest[j+1:]
						if len(value) > 0 && value[0] == '=' {
							value = value[1:]
						}
					} else {
						if i+1 >= n {
							usageErrorMissingValue("--flags <FLAGS>")
							return args, 2, true
						}
						value = argv[i+1]
						i++
					}
					args.flags = value
					setFlags = append(setFlags, "--flags")
					j = len(rest)
				default:
					usageErrorUnknown("-"+string(ch), setFlags)
					return args, 2, true
				}
				_ = consumed
			}
			i++
			continue
		}
