			// We'll see specifically
			if len(positional) >= 2 {
				// [FILES]... - clap reports "a value is required for '[FILES]...' but none was supplied"
				usageErrorEmptyValue("[FILES]...")
				return args, 2, true
			}
		}
		positional = append(positional, arg)
		i++
	}

	if len(positional) < 1 {
		usageErrorMissingArgs([]string{"<FIND>", "<REPLACE_WITH>"}, setFlags)
		return args, 2, true
	}
	if len(positional) < 2 {
		usageErrorMissingArgs([]string{"<REPLACE_WITH>"}, setFlags)
		return args, 2, true
	}
	args.find = positional[0]
	args.replaceWith = positional[1]
	if len(positional) > 2 {
		// Check for empty files arguments
		for _, f := range positional[2:] {
			if f == "" {
				usageErrorEmptyValue("[FILES]...")
				return args, 2, true
			}
		}
		args.files = positional[2:]
	}
	return args, 0, false
}

func usageLine(setFlags []string) string {
	if len(setFlags) == 0 {
		return "Usage: executable <FIND> <REPLACE_WITH> [FILES]..."
	}
	// Deduplicate
	seen := map[string]bool{}
	uniq := []string{}
	for _, f := range setFlags {
		if !seen[f] {
			seen[f] = true
			uniq = append(uniq, f)
		}
	}
	return "Usage: executable " + strings.Join(uniq, " ") + " <FIND> <REPLACE_WITH> [FILES]..."
}

func usageErrorUnknown(arg string, setFlags []string) {
	fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n", arg)
	fmt.Fprintf(os.Stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg)
	fmt.Fprintln(os.Stderr, "Usage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...")
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorMissingValue(flagDesc string) {
	fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\n", flagDesc)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorEmptyValue(flagDesc string) {
	fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\n", flagDesc)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorInvalidValue(value, flagDesc string, err error) {
	msg := err.Error()
	if nerr, ok := err.(*strconv.NumError); ok {
		switch nerr.Err.Error() {
		case "value out of range":
			msg = "number too large to fit in target type"
		case "invalid syntax":
			msg = "invalid digit found in string"
		}
	}
	fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '%s': %s\n\n", value, flagDesc, msg)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorUnexpectedValue(flag string, setFlags []string) {
	// clap message for providing value to a flag that doesn't take one
	fmt.Fprintf(os.Stderr, "error: unexpected value provided for '%s'\n\n", flag)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}

func usageErrorMissingArgs(missing []string, setFlags []string) {
	fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
	for _, m := range missing {
		fmt.Fprintln(os.Stderr, "  "+m)
	}
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, usageLine(setFlags))
	fmt.Fprintln(os.Stderr, "")
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
}
