			if err := writeAtomic(f, []byte(output)); err != nil {
				return formatFileError(err)
			}
		}
	}
	return nil
}

func formatFileError(err error) error {
	// Convert OS errors to sd's format
	msg := err.Error()
	// os.PathError prefix - strip to get inner
	var inner string
	if pe, ok := err.(*os.PathError); ok {
		inner = pe.Err.Error()
		// Extract errno for "os error XX"
		errno := osErrno(pe.Err)
		if errno != 0 {
			return fmt.Errorf("error: %s (os error %d)", capitalize(inner), errno)
		}
	}
	_ = inner
	return fmt.Errorf("error: %s", msg)
}

