package main

import (
	"fmt"
	"regexp"
	"strings"
	"syscall"
	"unicode"
)

// buildRegex builds a regex from the find pattern, flags string, and fixed-strings mode
func buildRegex(find string, flagStr string, fixedStrings bool) (*regexp.Regexp, error) {
	pattern := find
	if fixedStrings {
		pattern = regexp.QuoteMeta(pattern)
	}

	// Process flag characters in order
	// Defaults: multi_line=true
	caseInsensitive := false
	multiLine := true
	dotAll := false
	// word is applied inline on pattern; after 'w', all flags reset to builder defaults

	for _, c := range flagStr {
		switch c {
		case 'c':
			caseInsensitive = false
		case 'i':
			caseInsensitive = true
		case 'e':
			multiLine = false
		case 'm':
			// no-op; multi-line already on by default
		case 's':
			dotAll = true
		case 'w':
			pattern = `\b` + pattern + `\b`
			caseInsensitive = false
			multiLine = false
			dotAll = false
		default:
			// ignore unknown flag characters
		}
