// rewriteRegexError converts a Go regex error to a Rust-regex-style error message
// matching the format used by sd.
func rewriteGoRegexError(err error, pattern string) error {
	msg := err.Error()
	// Go format: "error parsing regexp: <desc>: `<ctx>`"
	var desc, ctx string
	if strings.HasPrefix(msg, "error parsing regexp: ") {
		rest := msg[len("error parsing regexp: "):]
		if idx := strings.LastIndex(rest, ": `"); idx >= 0 {
			desc = rest[:idx]
