			ctx = rest[idx+3:]
			if strings.HasSuffix(ctx, "`") {
				ctx = ctx[:len(ctx)-1]
			}
		} else {
			desc = rest
		}
	} else {
		desc = msg
	}

	// Map descriptions
	rustDesc := mapRegexErrorDesc(desc)

	// Find where in the pattern the error occurred
	// Use ctx to locate it
	pos := 0
	length := len(ctx)
	if ctx != "" {
		idx := strings.Index(pattern, ctx)
		if idx >= 0 {
			pos = idx
		}
	}

	// Build Rust-style error message
	var sb strings.Builder
	sb.WriteString("error: invalid regex regex parse error:\n")
	sb.WriteString("    ")
	sb.WriteString(pattern)
	sb.WriteString("\n")
	sb.WriteString("    ")
	sb.WriteString(strings.Repeat(" ", pos))
	if length == 0 {
		length = 1
	}
	sb.WriteString(strings.Repeat("^", length))
	sb.WriteString("\nerror: ")
	sb.WriteString(rustDesc)
	return fmt.Errorf("%s", sb.String())
}

