package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func run(args cliArgs) error {
	// Build the regex
	re, err := buildRegex(args.find, args.flags, args.fixedStrings)
	if err != nil {
		return err
	}

	// Validate replacement text (non-fixed mode: check $N followed by alpha)
	replacement := args.replaceWith
	if !args.fixedStrings {
		if err := validateReplacement(replacement); err != nil {
			return err
		}
		replacement = unescapeReplacement(replacement)
	}

	// Validate input files FIRST (before any modification)
	for _, f := range args.files {
		if _, err := os.Lstat(f); err != nil {
			return fmt.Errorf("error: invalid path: %s", f)
		}
	}

	// If no files, read from stdin
	if len(args.files) == 0 {
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			return fmt.Errorf("error: %s", err.Error())
		}
		output := applyReplace(re, string(input), replacement, args.maxReplacements, args.fixedStrings)
		os.Stdout.WriteString(output)
		return nil
	}

	// Process each file
	for _, f := range args.files {
		data, err := readFile(f)
		if err != nil {
			return err
		}
		output := applyReplace(re, string(data), replacement, args.maxReplacements, args.fixedStrings)

		if args.preview {
			if len(args.files) > 1 {
				fmt.Printf("----- FILE %s -----\n", f)
			}
			os.Stdout.WriteString(output)
		} else {
			if err := writeAtomic(f, []byte(output)); err != nil {
				return err
			}
		}
	}
	return nil
}

// readFile reads a file like sd does, emitting "No such device" for non-regular files.
func readFile(path string) ([]byte, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("error: %s", err.Error())
	}
	if !info.Mode().IsRegular() {
		// sd uses memory mapping which fails with ENODEV for non-regular files
		return nil, fmt.Errorf("error: No such device (os error 19)")
	}
	// Check readability
	f, err := os.Open(path)
	if err != nil {
		if os.IsPermission(err) {
			return nil, fmt.Errorf("error: Permission denied (os error 13)")
		}
		return nil, fmt.Errorf("error: %s", err.Error())
	}
	defer f.Close()
	data, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("error: %s", err.Error())
	}
	return data, nil
}

func writeAtomic(path string, data []byte) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("error: %s", err.Error())
	}
	// Write to temp file in same directory
	dir := "."
	if idx := strings.LastIndex(path, "/"); idx >= 0 {
		dir = path[:idx]
		if dir == "" {
			dir = "/"
		}
	}
	tmp, err := os.CreateTemp(dir, ".sdtmp-*")
	if err != nil {
		return fmt.Errorf("error: %s", err.Error())
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return fmt.Errorf("error: %s", err.Error())
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("error: %s", err.Error())
	}
	if err := os.Chmod(tmpName, info.Mode().Perm()); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("error: %s", err.Error())
	}
	if err := os.Rename(tmpName, path); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("error: %s", err.Error())
	}
	return nil
}
