package main

import (
	"fmt"
	"regexp"
	"strings"
)

// rewriteGoRegexError converts a Go regex error to a Rust-regex-style error message
// matching the format used by sd.
// fullPattern is what was sent to Go's regex.Compile (may include flag prefix).
// origPattern is what the user typed.
// prefixLen is how much of the fullPattern is our added prefix.
func rewriteGoRegexError(err error, fullPattern, origPattern string, prefixLen int) error {
	msg := err.Error()
	var desc, ctx string
	if strings.HasPrefix(msg, "error parsing regexp: ") {
		rest := msg[len("error parsing regexp: "):]
		if idx := strings.LastIndex(rest, ": `"); idx >= 0 {
			desc = rest[:idx]
			ctx = rest[idx+3:]
			if strings.HasSuffix(ctx, "`") {
				ctx = ctx[:len(ctx)-1]
			}
		} else {
			desc = rest
		}
	} else {
		desc = msg
	}

	rustDesc := mapRegexErrorDesc(desc)

	// Find position in origPattern
	// First, try exact match in origPattern
	pos := 0
	length := len(ctx)
	if ctx != "" {
		// Try to strip our flag prefix from ctx
		trimmedCtx := ctx
		if prefixLen > 0 && strings.HasPrefix(ctx, fullPattern[:prefixLen]) {
			trimmedCtx = ctx[prefixLen:]
		}
		if idx := strings.Index(origPattern, trimmedCtx); idx >= 0 {
			pos = idx
			length = len(trimmedCtx)
		} else if idx := strings.Index(origPattern, ctx); idx >= 0 {
			pos = idx
			length = len(ctx)
		} else {
			// Can't find exact context; use position 0
			length = 1
		}
	}

	var sb strings.Builder
	sb.WriteString("error: invalid regex regex parse error:\n")
	sb.WriteString("    ")
	sb.WriteString(origPattern)
	sb.WriteString("\n")
	sb.WriteString("    ")
	sb.WriteString(strings.Repeat(" ", pos))
	if length == 0 {
		length = 1
	}
	sb.WriteString(strings.Repeat("^", length))
	sb.WriteString("\nerror: ")
	sb.WriteString(rustDesc)
	return fmt.Errorf("%s", sb.String())
}

func mapRegexErrorDesc(desc string) string {
	switch {
	case strings.HasPrefix(desc, "missing closing ]"):
		return "unclosed character class"
	case strings.HasPrefix(desc, "missing closing )"):
		return "unclosed group"
	case strings.Contains(desc, "invalid or unsupported Perl syntax"):
		return "look-around, including look-ahead and look-behind, is not supported"
	case strings.HasPrefix(desc, "trailing backslash"):
		return "incomplete escape sequence, reached end of pattern prematurely"
	case strings.HasPrefix(desc, "invalid repeat count"):
		return "invalid repeat count"
	case strings.HasPrefix(desc, "invalid character class range"):
		return "invalid character class range"
	case strings.HasPrefix(desc, "invalid nested repetition operator"):
		return "invalid nested repetition operator"
	case strings.HasPrefix(desc, "invalid escape sequence"):
		return "invalid escape sequence"
	}
	return desc
}

func compileWithStyledError(fullPattern, origPattern string, prefixLen int) (*regexp.Regexp, error) {
	re, err := regexp.Compile(fullPattern)
	if err != nil {
		return nil, rewriteGoRegexError(err, fullPattern, origPattern, prefixLen)
	}
	return re, nil
}
